#!/usr/bin/env python3
"""Safely add Toonami Aftermath West listings generated by the upstream CLI."""
import gzip
import json
import re
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

TARGET = "ToonamiAftermath.us@West"
def main():
    report = {"target": TARGET, "status": "not_added"}
    path = Path("toonami.xml")
    if not path.exists():
        report["reason"] = "No upstream XMLTV file generated"
    else:
        root = ET.parse(path).getroot()
        candidates = []
        for ch in root.findall("channel"):
            names = [n.text or "" for n in ch.findall("display-name")]
            label = " ".join([ch.get("id") or ""] + names).lower()
            if re.search(r"(^|[^a-z])(west|pacific|pst)([^a-z]|$)", label):
                candidates.append((ch, names))
        report["candidate_channels"] = [{"id":ch.get("id"),"names":names} for ch,names in candidates]
        if len(candidates) == 1:
            channel = candidates[0][0]
            programmes = [p for p in root.findall("programme") if p.get("channel") == channel.get("id") and p.findtext("title")]
            report["programme_count"] = len(programmes)
            if len(programmes) >= 4:
                with gzip.open("epg-preview.xml.gz","rb") as fh:
                    original = fh.read()
                if b'channel="ToonamiAftermath.us@West"' in original:
                    report["status"] = "already_present"
                else:
                    channel.set("id",TARGET)
                    fragments = [ET.tostring(channel,encoding="utf-8")]
                    for p in programmes:
                        p.set("channel",TARGET)
                        fragments.append(ET.tostring(p,encoding="utf-8"))
                    marker = original.rfind(b"</tv>")
                    if marker < 0:
                        raise ValueError("Invalid preview XMLTV")
                    with gzip.open("epg-preview.xml.gz","wb") as fh:
                        fh.write(original[:marker] + b"\n" + b"\n".join(fragments) + b"\n" + original[marker:])
                    report["status"] = "added"
            else:
                report["reason"] = "West/Pacific channel is not uniquely identified; no guess made"
    Path("toonami-integration-report.json").write_text(json.dumps(report,indent=2)+"\n")
    print(json.dumps(report,indent=2))
if __name__ == "__main__":
    main()
